from pathlib import Path
import json,numpy as np
from PIL import Image,ImageDraw
P=Path('character/crew-height-check-v1');P.mkdir(exist_ok=True);tracks=[];report={};sheet=Image.new('RGB',(960,880),'#303b40');draw=ImageDraw.Draw(sheet)
for row,d in enumerate(['south','east','north','west']):
 for col,who in enumerate(['bill','veld','branforth']):
  root=Path('character/bill-material-match-v1')/d if who=='bill' else Path('character/crew-runtime-matte-v1')/who
  m=json.loads((root/'manifest.json').read_text());s=next(s for s in m['states'] if s['id']=='walk-'+d);ims=[Image.open(root/f).convert('RGBA') for f in s['frameFiles']];tops=[];heights=[]
  for im in ims:
   a=np.array(im);yy,xx=np.where(a[:,:,3]>127);tops.append(int(yy.min()));heights.append(int(yy.max()-yy.min()+1))
  pivot=m['pivot'];standing=m['standingHeight'];i=int(np.argsort(tops)[len(tops)//2]);im=ims[i];x=col*320+68;y=row*220+27;sheet.paste(im,(x,y),im);draw.line((col*320+20,y+172,col*320+300,y+172),fill='#83a49c');draw.text((col*320+8,row*220+5),f'{who} {d} / head height {172-np.median(tops):.1f}px',fill='white')
  report[who+'-'+d]=dict(frames=len(ims),pivot=pivot,standingHeight=standing,headAbovePivotMedian=float(pivot[1]-np.median(tops)),headAbovePivotRange=[float(pivot[1]-max(tops)),float(pivot[1]-min(tops))],occupiedHeightRange=[min(heights),max(heights)])
  tracks.append(dict(label=who.title()+' '+d,row=row,col=col,files=['../'+str(root.relative_to('character')).replace('\\','/')+'/'+f for f in s['frameFiles']],durations=s['frameDurationsMs']))
sheet.save(P/'height-contact.png');(P/'measurements.json').write_text(json.dumps(report,indent=2));print(json.dumps(report))
html='''<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{background:#172226;color:#dbe4df;font:17px system-ui;max-width:1100px;margin:24px auto;padding:16px}canvas,img{width:100%;height:auto}button,select{font:inherit}</style><h1>Crew height check</h1><p>Bill latest selected candidate; Veld and Branforth installed walks. Same 184px canvas, 148px standing reference and foot pivot. Rows: south, east, north, west. No individual resizing.</p><button id="pause">Pause</button> <select id="scale"><option value="1">148px inspection</option><option value=".554">82px gameplay</option><option value=".365">54px gameplay</option><option value=".182">27px gameplay</option></select><p id="status">Loading frames...</p><canvas id="board" width="960" height="880"></canvas><h2>Median head-height poses</h2><img src="height-contact.png"><script>const tracks=TRACKS;let ready=false,playing=true,t=0,last=0;const ctx=document.getElementById('board').getContext('2d');Promise.all(tracks.map(async s=>{s.images=await Promise.all(s.files.map(src=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=reject;im.src=src})));s.total=s.durations.reduce((a,b)=>a+b,0)})).then(()=>{ready=true;document.getElementById('status').textContent='All frames loaded'});document.getElementById('pause').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause':'Play'};function draw(now){if(last&&playing)t+=now-last;last=now;if(ready){ctx.fillStyle='#303b40';ctx.fillRect(0,0,960,880);const z=Number(document.getElementById('scale').value);tracks.forEach(s=>{let time=t%s.total,i=0;while(i<s.images.length-1&&time>=s.durations[i])time-=s.durations[i++];const cx=s.col*320+160,base=s.row*220+199;ctx.strokeStyle='#83a49c';ctx.beginPath();ctx.moveTo(s.col*320+20,base);ctx.lineTo(s.col*320+300,base);ctx.stroke();ctx.fillStyle='#dbe4df';ctx.font='16px system-ui';ctx.fillText(s.label,s.col*320+10,s.row*220+20);ctx.drawImage(s.images[i],cx-92*z,base-172*z,184*z,184*z)})}requestAnimationFrame(draw)}requestAnimationFrame(draw);</script>''';(P/'index.html').write_text(html.replace('TRACKS',json.dumps(tracks)))
